package au.aumanet.app;
import java.util.*;import java.util.concurrent.*;import java.util.concurrent.atomic.*;import org.json.*;
/** Exact controller guards and synchronous retirement; declared group/service boundaries. */
public final class NodeUpdateGuardTest{
 static int tests,assertions;static void check(boolean b){assertions++;if(!b)throw new AssertionError("Update owner/Stop guard regression");}
 static final String PROCESS="11111111-1111-1111-1111-111111111111",OWNER="A".repeat(64),PEER="B".repeat(64),GROUP="2".repeat(32);static final Set<String>PINS=Set.of(OWNER,PEER);
 static TrustedConnectionScope saved(Object source,long generation){return new TrustedConnectionScope(source,PROCESS,OWNER,GROUP,OWNER,1,generation,PINS,true,true,false);}
 static InternetSharingScope scope(Object source,android.net.Network network,long run){return new InternetSharingScope(source,PROCESS,OWNER,GROUP,OWNER,1,run,network,"10.77.0.10",PINS,PINS);}
 static NodeUpdateGuardHarness setup(){SystemClock.now=100;TrustedConnectionController.epoch=1;NodeUpdateService.available=true;NodeUpdateGuardHarness h=new NodeUpdateGuardHarness();Object source=new Object();h.group.saved=saved(source,2);h.group.scope=scope(source,new android.net.Network(),2);h.config=new Object();NodeUpdateGuardHarness.Operation o=new NodeUpdateGuardHarness.Operation();o.saved=h.group.saved;o.group=h.group.scope;o.config=h.config;o.started=100;o.wall=System.currentTimeMillis();o.deadline=10000;o.confirmBefore=9000;o.intentEpoch=1;o.ticket=new NodeUpdateMaintenance.Ticket();h.current.set(o);return h;}
 static void unchanged(){tests++;NodeUpdateGuardHarness h=setup();NodeUpdateGuardHarness.Operation o=h.current.get();check(h.operationLive(o)&&h.preboot(o));o.activated=true;check(h.postboot(o));h.issuer.retained=false;check(!h.preboot(o)&&h.postboot(o));h.group.scope=null;check(h.postboot(o));}
 static void stopAndLoss(){tests++;for(int mode=0;mode<8;mode++){NodeUpdateGuardHarness h=setup();NodeUpdateGuardHarness.Operation o=h.current.get();o.activated=true;switch(mode){case 0->TrustedConnectionController.epoch++;case 1->o.cancelled.set(true);case 2->h.config=new Object();case 3->h.group.saved=saved(new Object(),2);case 4->o.ticket.retained=false;case 5->NodeUpdateService.available=false;case 6->SystemClock.now=o.deadline;case 7->SystemClock.now=o.confirmBefore;}check(!h.postboot(o));if(mode<4||mode==6)check(!h.operationLive(o));}}
 static void clocks(){tests++;NodeUpdateGuardHarness h=setup();NodeUpdateGuardHarness.Operation o=h.current.get();SystemClock.now=99;check(!h.operationLive(o));SystemClock.now=6100;check(!h.operationLive(o));SystemClock.now=100;o.wall=System.currentTimeMillis()+10000;check(!h.operationLive(o));}
 static void oldRetirement()throws Exception{tests++;NodeUpdateGuardHarness h=setup();NodeUpdateGuardHarness.Operation old=h.current.get(),replacement=new NodeUpdateGuardHarness.Operation();h.current.set(replacement);h.retire(old);check(!old.cancelled.get()&&!replacement.cancelled.get());CountDownLatch entered=new CountDownLatch(1),release=new CountDownLatch(1);replacement.resource.set(()->{entered.countDown();try{release.await(2,TimeUnit.SECONDS);}catch(InterruptedException ignored){}});long began=System.nanoTime();h.retire(replacement);check((System.nanoTime()-began)/1000000<250);check(replacement.cancelled.get()&&replacement.resource.get()==null);check(entered.await(1,TimeUnit.SECONDS));release.countDown();}
 public static void main(String[]args)throws Exception{unchanged();stopAndLoss();clocks();oldRetirement();System.out.println(new JSONObject().put("status","pass").put("testCount",tests).put("assertionCount",assertions));}
}
